import React from "react";
import {
  Routes,
  Route,
  Navigate
} from "react-router-dom";

import Sidebar from "./components/Sidebar";
import Login from "./pages/Login";
import Dashboard from "./pages/Dashboard";
import Threats from "./pages/Threats";
import Incidents from "./pages/Incidents";
import Packets from "./pages/Packets";
import Settings from "./pages/Settings";

function App() {
  const token =
    localStorage.getItem(
      "access_token"
    );

  // Not logged in → show login
  if (!token) {
    return <Login />;
  }

  // Logged in → show dashboard + sidebar
  return (
    <div style={styles.app}>
      <Sidebar />

      <div style={styles.content}>
        <Routes>
          {/* default page */}
          <Route
            path="/"
            element={
              <Navigate
                to="/dashboard"
              />
            }
          />

          <Route
            path="/dashboard"
            element={<Dashboard />}
          />

          <Route
            path="/threats"
            element={<Threats />}
          />

          <Route
            path="/incidents"
            element={<Incidents />}
          />

          <Route
            path="/packets"
            element={<Packets />}
          />

          <Route
            path="/settings"
            element={<Settings />}
          />

          {/* fallback */}
          <Route
            path="*"
            element={
              <Navigate
                to="/dashboard"
              />
            }
          />
        </Routes>
      </div>
    </div>
  );
}

const styles = {
  app: {
    display: "flex",
    background: "#0f172a",
    color: "white",
    minHeight: "100vh"
  },

  content: {
    flex: 1,
    padding: "20px"
  }
};

export default App;
